import os
import sys
import time
import requests
from urllib.parse import urlparse
from pathlib import Path

def sanitize_filename(url):
    parsed = urlparse(url)
    path = parsed.path
    if not path:
        path = '/'
    sanitized = []
    for c in path:
        if c.isalnum() or c in ('-', '_'):
            sanitized.append(c)
        else:
            sanitized.append('_')
    return ''.join(sanitized) + '.body'

def process_url(url):
    cache_dir = Path('body_cache')
    cache_dir.mkdir(exist_ok=True)
    cache_file = cache_dir / sanitize_filename(url)

    if cache_file.exists():
        mod_time = cache_file.stat().st_mtime
        if time.time() - mod_time < 600:
            return url, 'CACHED', cache_file.stat().st_size

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        body = response.content
        cache_file.write_bytes(body)
        return url, str(response.status_code), len(body)
    except requests.RequestException:
        return url, 'ERROR', 0

def main():
    urls = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            urls.append(line)

    for url in urls:
        url, status, byte_count = process_url(url)
        print(f"{url}\t{status}\t{byte_count}")

if __name__ == "__main__":
    main()

import os
import re
import shutil
import stat
import sys
import time
import urllib.parse
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError

def sanitize_filename(url):
    sanitized = re.sub(r'[^a-zA-Z0-9\-_]', '_', url)
    return sanitized + '.body'

def process_url(url):
    cache_dir = 'body_cache'
    os.makedirs(cache_dir, exist_ok=True)
    cache_file = os.path.join(cache_dir, sanitize_filename(url))

    if os.path.exists(cache_file):
        mod_time = os.path.getmtime(cache_file)
        if time.time() - mod_time < 600:
            return url, 'CACHED', os.path.getsize(cache_file)

    try:
        req = Request(url, timeout=10)
        with urlopen(req) as response:
            body = response.read()
            os.makedirs(cache_dir, exist_ok=True)
            with open(cache_file, 'wb') as f:
                f.write(body)
            return url, str(response.getcode()), len(body)
    except (URLError, HTTPError):
        return url, 'ERROR', 0

def main():
    urls = []
    for line in sys.stdin:
        stripped = line.rstrip('\r\n')
        if stripped:
            urls.append(stripped)

    for url in urls:
        url, status, byte_count = process_url(url)
        print(f"{url}\t{status}\t{byte_count}")

if __name__ == '__main__':
    main()
